// Składa jeden mail z trzech list: bez PO, bez ETA (+ bez magazynu) i braki dokumentów.
const PANEL = 'http://192.0.2.10:81';   // adres panelu dla linków w mailu
const RULES = {
  containers_no_po: 'Kontenery w obiegu bez numeru zamówienia (PO)',
  containers_no_eta: 'Kontenery w transporcie / porcie bez ETA',
  containers_no_warehouse: 'Kontenery bez magazynu ze słownika',
};
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const link = (id, label) => `<a href="${PANEL}/kontenery/${id}">${esc(label)}</a>`;

const quality = $('Jakość danych').first().json;
const gaps = $('Braki dokumentów').all().map(i => i.json).filter(g => g.container_no);

let total = 0;
const parts = [];
for (const issue of quality.issues || []) {
  if (!RULES[issue.key] || !issue.count) continue;
  total += issue.count;
  const more = issue.count > issue.items.length ? `<li>… i ${issue.count - issue.items.length} więcej (pełna lista: Master data → Jakość danych)</li>` : '';
  parts.push(`<h3>${RULES[issue.key]} (${issue.count})</h3><ul>` +
    issue.items.map(i => `<li>${link(i.id, i.label)}</li>`).join('') + more + '</ul>');
}
if (gaps.length) {
  total += gaps.length;
  parts.push(`<h3>Brakujące dokumenty przed ETA (${gaps.length})</h3><ul>` +
    gaps.map(g => `<li>${link(g.id, g.container_no)} — ETA ${esc(g.eta || '?')}: brak ${esc((g.missing || []).join(', '))}</li>`).join('') + '</ul>');
}
const today = new Date().toISOString().slice(0, 10);
return [{ json: {
  total,
  subject: `TIMPORYE — ${total} braków w danych do uzupełnienia (${today})`,
  html: `<p>Dzień dobry, poniżej kontenery z brakami. Kliknij numer, żeby otworzyć kartę w panelu.</p>${parts.join('')}<p style="color:#888">Raport automatyczny z n8n (workflow „Kontrola danych”).</p>`,
} }];
